$seed_json$::jsonb) AS j;

INSERT INTO person (name)
SELECT DISTINCT e.name
FROM (
    SELECT x AS name FROM _seed_movie s CROSS JOIN LATERAL jsonb_array_elements_text(s.j -> 'directors') x
    UNION ALL
    SELECT x AS name FROM _seed_movie s CROSS JOIN LATERAL jsonb_array_elements_text(s.j -> 'cast_top') x
) e
ON CONFLICT (name) DO NOTHING;

INSERT INTO genre (name)
SELECT DISTINCT x
FROM _seed_movie s
CROSS JOIN LATERAL jsonb_array_elements_text(s.j -> 'genres') x
ON CONFLICT (name) DO NOTHING;

INSERT INTO keyword (name)
SELECT DISTINCT x
FROM _seed_movie s
CROSS JOIN LATERAL jsonb_array_elements_text(s.j -> 'keywords') x
ON CONFLICT (name) DO NOTHING;

INSERT INTO movie
    (title, original_title, overview, release_year, runtime_minutes,
     original_language, poster_path, backdrop_path, tmdb_id)
SELECT
    s.j ->> 'title',
    s.j ->> 'original_title',
    s.j ->> 'overview',
    (s.j ->> 'release_year')::smallint,
    (s.j ->> 'runtime_minutes')::smallint,
    (s.j ->> 'original_language')::char(2),
    s.j ->> 'poster_path',
    s.j ->> 'backdrop_path',
    (s.j ->> 'tmdb_id')::bigint
FROM _seed_movie s
ON CONFLICT (tmdb_id) DO UPDATE SET
    title             = EXCLUDED.title,
    original_title    = EXCLUDED.original_title,
    overview          = EXCLUDED.overview,
    release_year      = EXCLUDED.release_year,
    runtime_minutes   = EXCLUDED.runtime_minutes,
    original_language = EXCLUDED.original_language,
    poster_path       = EXCLUDED.poster_path,
    backdrop_path     = EXCLUDED.backdrop_path;

DELETE FROM movie_director
WHERE movie_id IN (
    SELECT m.id
    FROM movie m
    JOIN _seed_movie s
      ON m.tmdb_id = (s.j ->> 'tmdb_id')::bigint
);

DELETE FROM movie_cast
WHERE movie_id IN (
    SELECT m.id
    FROM movie m
    JOIN _seed_movie s
      ON m.tmdb_id = (s.j ->> 'tmdb_id')::bigint
);

DELETE FROM movie_genre
WHERE movie_id IN (
    SELECT m.id
    FROM movie m
    JOIN _seed_movie s
      ON m.tmdb_id = (s.j ->> 'tmdb_id')::bigint
);

DELETE FROM movie_keyword
WHERE movie_id IN (
    SELECT m.id
    FROM movie m
    JOIN _seed_movie s
      ON m.tmdb_id = (s.j ->> 'tmdb_id')::bigint
);

INSERT INTO movie_director (movie_id, person_id, position)
SELECT m.id, p.id, d.pos::smallint
FROM _seed_movie s
CROSS JOIN LATERAL jsonb_array_elements_text(s.j -> 'directors') WITH ORDINALITY AS d(name, pos)
JOIN movie m
  ON m.tmdb_id = (s.j ->> 'tmdb_id')::bigint
JOIN person p ON p.name = d.name;

INSERT INTO movie_cast (movie_id, person_id, position)
SELECT m.id, p.id, c.pos::smallint
FROM _seed_movie s
CROSS JOIN LATERAL jsonb_array_elements_text(s.j -> 'cast_top') WITH ORDINALITY AS c(name, pos)
JOIN movie m
  ON m.tmdb_id = (s.j ->> 'tmdb_id')::bigint
JOIN person p ON p.name = c.name;

INSERT INTO movie_genre (movie_id, genre_id, position)
SELECT m.id, g.id, gn.pos::smallint
FROM _seed_movie s
CROSS JOIN LATERAL jsonb_array_elements_text(s.j -> 'genres') WITH ORDINALITY AS gn(name, pos)
JOIN movie m
  ON m.tmdb_id = (s.j ->> 'tmdb_id')::bigint
JOIN genre g ON g.name = gn.name;

INSERT INTO movie_keyword (movie_id, keyword_id, position)
SELECT m.id, k.id, kw.pos::smallint
FROM _seed_movie s
CROSS JOIN LATERAL jsonb_array_elements_text(s.j -> 'keywords') WITH ORDINALITY AS kw(name, pos)
JOIN movie m
  ON m.tmdb_id = (s.j ->> 'tmdb_id')::bigint
JOIN keyword k ON k.name = kw.name;

DROP TABLE _seed_movie;
